import{_ as i,c as t,o,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"MODIFYING RECIPROCAL TARIFF RATES TO REFLECT DISCUSSIONS WITH THE PEOPLE’S REPUBLIC OF CHINA","description":"","frontmatter":{"title":"MODIFYING RECIPROCAL TARIFF RATES TO REFLECT DISCUSSIONS WITH THE PEOPLE’S REPUBLIC OF CHINA","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china/","publishDate":"2025-05-12T18:31:16-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-12-modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china.md","filePath":"executive-orders/2025-05-12-modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china.md"}'),s={name:"executive-orders/2025-05-12-modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china.md"};function a(n,e,l,c,d,p){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-people-s-republic-of-china" tabindex="-1">MODIFYING RECIPROCAL TARIFF RATES TO REFLECT DISCUSSIONS WITH THE PEOPLE’S REPUBLIC OF CHINA <a class="header-anchor" href="#modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-people-s-republic-of-china" aria-label="Permalink to &quot;MODIFYING RECIPROCAL TARIFF RATES TO REFLECT DISCUSSIONS WITH THE PEOPLE’S REPUBLIC OF CHINA&quot;">​</a></h1><p>Published: Monday, May 12, 2025</p><ul><li><p><strong>Authority</strong>: The President has the authority to issue this executive order under various U.S. laws, including the International Emergency Economic Powers Act and the National Emergencies Act.</p></li><li><p><strong>National Emergency Declaration</strong>:</p><ul><li>Declared in Executive Order 14257 due to large and persistent U.S. goods trade deficits, posing a threat to national security and the economy.</li><li>Imposed additional duties on imports to counter this threat.</li></ul></li><li><p><strong>Retaliatory Measures</strong>:</p><ul><li>Executive Order 14257 allows modifications to duties if trading partners retaliate through import duties or other measures.</li><li>In response to China’s announced retaliation, subsequent orders (14259 and 14266) raised applicable duty rates on imports from China.</li></ul></li><li><p><strong>Reciprocal Trade Discussions</strong>:</p><ul><li>Discussions with China are ongoing to address trade reciprocity and security concerns, seen as a step toward remedying non-reciprocal trade arrangements.</li></ul></li><li><p><strong>Modification of Tariff Schedule</strong>:</p><ul><li>Additional duties on imports from China will be suspended for 90 days starting May 14, 2025, with a new duty rate of 10% prescribed.</li><li>Specific changes to the Harmonized Tariff Schedule (HTSUS) include modifications to duty rates and descriptions of affected articles.</li></ul></li><li><p><strong>Additional Duty Changes</strong>:</p><ul><li>Reduction of duty rates from 120% to 54% for certain items related to synthetic opioids from China.</li><li>Retention of a postal item duty rate of $100 until modified by subsequent action.</li></ul></li><li><p><strong>Implementation Team</strong>:</p><ul><li>Various government officials, including the Secretaries of Commerce and Homeland Security, are directed to implement this order and necessary regulatory changes.</li></ul></li><li><p><strong>Legal and Administrative Provisions</strong>:</p><ul><li>The order does not impair existing agency authorities or the functions of the Office of Management and Budget.</li><li>It does not create enforceable rights against the U.S. or its entities.</li></ul></li><li><p><strong>Publication Costs</strong>:</p><ul><li>Costs associated with the publication of the order will be covered by the Department of Commerce.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/modifying-reciprocal-tariff-rates-to-reflect-discussions-with-the-peoples-republic-of-china/</a></p>',4)]))}const h=i(s,[["render",a]]);export{f as __pageData,h as default};
